import csv
import io


def parse_csv(raw_csv: str):
    text = raw_csv.lstrip("\ufeff")
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=",", quotechar='"')

    records = []
    for row in reader:
        if row and any(value.strip() for value in row):
            records.append(row)

    if not records:
        return {"columns": [], "rows": []}

    width = 2
    header_index = next(
        (i for i, row in enumerate(records) if len(row) == width),
        next((i for i, row in enumerate(records) if len(row) > 1), 0),
    )

    def normalize(row):
        row = list(row)
        if len(row) < width:
            row.extend([""] * (width - len(row)))
        elif len(row) > width:
            row = row[:width - 1] + [",".join(row[width - 1:])]
        return row

    columns = normalize(records[header_index])
    rows = [normalize(row) for row in records[header_index + 1:]]
    return {"columns": columns, "rows": rows}
